#!/usr/bin/env bash
# Move one service's state from the host that runs it to the host that should.
#
#   bash scripts/task/offload-migrate.sh paperless [--dry-run]
#   bash scripts/task/offload-migrate.sh vaultwarden
#
# Reads the same JSON the shelter bridge reads (`/var/lib/offload-bridge/config.json`,
# generated by `modules/services/offload-bridge.nix`), so the paths a migration
# uses and the paths a nightly push protects cannot drift apart.
#
# Two properties this script exists to hold, in this order:
#
#  1. **One migration at a time.** A lock file, taken non-blocking. Two copies of
#     this racing is how a service ends up half its own state and half the
#     other's, and the failure surfaces days later as a document with no file.
#  2. **Re-runnable.** The manifest makes a second run a no-op instead of a second
#     copy: stop, compare, copy only when the source changed, verify, start. An
#     interrupted run leaves a manifest that does not match, so the next run
#     copies again rather than trusting half a transfer.
set -euo pipefail

CONFIG="${BRIDGE_CONFIG:-/etc/offload-bridge/config.json}"
SET="${1:-}"
MODE="${2:-}"

die() {
  echo "offload-migrate: $*" >&2
  exit 1
}
say() { echo "== $*"; }

[ -n "$SET" ] || die "usage: offload-migrate.sh <set> [--dry-run]"
[ -r "$CONFIG" ] || die "cannot read $CONFIG"
case "$MODE" in "" | --dry-run) ;; *) die "unknown flag: $MODE" ;; esac
for tool in jq rsync ssh sqlite3 flock curl; do
  command -v "$tool" >/dev/null 2>&1 || die "missing tool: $tool"
done

jq -e --arg s "$SET" '.sets[$s]' "$CONFIG" >/dev/null || die "no set named '$SET' in $CONFIG"

SOURCE="$(jq -r --arg s "$SET" '.migrate[$s].source // .shelter.host' "$CONFIG")"
PATH_SRC="$(jq -er --arg s "$SET" '.sets[$s].path' "$CONFIG")"
PATH_DST="$PATH_SRC"
KEY="$(jq -er '.shelter.keyFile' "$CONFIG")"
KNOWN_HOSTS="$(jq -er '.shelter.knownHosts' "$CONFIG")"
STOP_SRC="$(jq -r --arg s "$SET" '(.migrate[$s].stopSource // []) | join(" ")' "$CONFIG")"
STOP_DST="$(jq -r --arg s "$SET" '(.migrate[$s].stopTarget // []) | join(" ")' "$CONFIG")"
COUNT_SQL="$(jq -r --arg s "$SET" '.migrate[$s].countSql // ""' "$CONFIG")"
HEALTH_URL="$(jq -r --arg s "$SET" '.migrate[$s].healthUrl // ""' "$CONFIG")"
STATE_DIR="/var/lib/offload-migrate"

mkdir -p "$(dirname "$KNOWN_HOSTS")" "$STATE_DIR"
SSH_OPTS=(-o BatchMode=yes -o ConnectTimeout=15 -o StrictHostKeyChecking=accept-new -o UserKnownHostsFile="$KNOWN_HOSTS" -i "$KEY")
rsh() { ssh "${SSH_OPTS[@]}" "$SOURCE" "$@"; }
# `sudo bash -lc` on the far side: the source tree belongs to a service user and
# this runs as root here, which is the one credential the fleet already shares.
rsudo() { rsh "sudo bash -lc $(printf '%q' "$1")"; }
RSYNC_RSH="ssh ${SSH_OPTS[*]}"

# --- 1. Concurrency claim ----------------------------------------------------
exec 9>"/run/lock/nixconfig-offload-migrate.lock"
flock -n 9 || die "another offload migration holds the lock ($(cat /run/lock/nixconfig-offload-migrate.lock 2>/dev/null || echo '?'))"

# The script itself wants root (it writes service trees); a nested `sudo` when
# already root is noise, and a `sudo -n` that cannot prompt is a silent no-op.
if [ "$(id -u)" -eq 0 ]; then SUDO=""; else SUDO="sudo -n"; fi

units_active() { # host_unit -> "active"
  local u="$1"
  if [ "$2" = local ]; then systemctl is-active --quiet "$u"; else rsh "systemctl is-active --quiet '$u'"; fi
}
stop_units() { # local|remote, list
  local where="$1" u
  for u in $2; do
    if [ "$where" = local ]; then $SUDO systemctl stop "$u" 2>/dev/null || true
    else rsudo "systemctl stop '$u' || true"; fi
    units_active "$u" "$where" && die "$u is still active on $where after stop"
    say "stopped $u ($where)"
  done
}
start_units() {
  local u
  for u in $1; do
    $SUDO systemctl start "$u" || die "failed to start $u"
    say "started $u"
  done
}

# --- 2. What the source currently holds -------------------------------------
# The database and its WAL sidecars are deliberately out of the manifest: they
# are never copied file-by-file, and stopping the source
# checkpoints the database, which deletes a `-wal` and changes the file count.
# Counting them made a second run re-copy 752 MB because the *stop* had changed
# the tree it was about to copy. The database is compared by row count instead.
source_manifest() {
  local expr=""
  local db
  while IFS= read -r db; do
    [ -n "$db" ] || continue
    expr="$expr -not -name $(printf '%q' "$db") -not -name $(printf '%q' "$db-wal") -not -name $(printf '%q' "$db-shm")"
  done < <(jq -r --arg s "$SET" '.sets[$s].sqlite[]?' "$CONFIG")
  rsudo "find '$PATH_SRC' -type f $expr -printf '%s %T@\n'" | awk '{n++; b += $1; if ($2 > m) m = $2} END {printf "%d %.0f %.0f", n, b, m}'
}
source_count() {
  [ -n "$COUNT_SQL" ] || return 0
  local db
  db="$(jq -r --arg s "$SET" '.sets[$s].sqlite[0] // empty' "$CONFIG")"
  [ -n "$db" ] || return 0
  rsudo "sqlite3 '$PATH_SRC/$db' \"$COUNT_SQL\"" 2>/dev/null || echo ""
}
local_count() {
  [ -n "$COUNT_SQL" ] || return 0
  local db
  db="$(jq -r --arg s "$SET" '.sets[$s].sqlite[0] // empty' "$CONFIG")"
  [ -n "$db" ] || return 0
  $SUDO sqlite3 "$PATH_DST/$db" "$COUNT_SQL" 2>/dev/null || echo ""
}

MANIFEST_FILE="$STATE_DIR/$SET.json"
BEFORE="$(source_manifest)"
REMOTE_COUNT="$(source_count)"
say "$SET: source $SOURCE holds $BEFORE (files bytes max-mtime), $([ -n "$COUNT_SQL" ] && echo "rows=$REMOTE_COUNT" || echo 'no row count')"

if [ -r "$MANIFEST_FILE" ]; then
  DONE_MANIFEST="$(jq -r '.manifest' "$MANIFEST_FILE")"
  same_rows=1
  if [ -n "$COUNT_SQL" ] && [ "$(local_count)" != "$REMOTE_COUNT" ]; then same_rows=0; fi
  if [ "$DONE_MANIFEST" = "$BEFORE" ] && [ "$same_rows" -eq 1 ]; then
    say "idempotent: source unchanged since the last migration and the target already matches — nothing to copy"
    start_units "$STOP_DST"
    exit 0
  fi
  say "source or target moved since the last run ($DONE_MANIFEST) — copying again"
fi

if [ "$MODE" = "--dry-run" ]; then
  say "dry run: would stop [$STOP_DST] here and [$STOP_SRC] on $SOURCE, mirror $PATH_SRC, take each database as a consistent snapshot, then start [$STOP_DST]"
  exit 0
fi

# --- 3. Cut over -------------------------------------------------------------
# The target is stopped first: it must not write into the tree that is about to
# be replaced. The source is stopped second, and only after this host is quiet.
stop_units local "$STOP_DST"
stop_units remote "$STOP_SRC"

install -d -m 0700 "$PATH_DST"
OWNER="$(stat -c '%u:%g' "$PATH_DST")"
say "mirroring $SOURCE:$PATH_SRC -> $PATH_DST (owner $OWNER)"

excludes=()
while IFS= read -r db; do
  [ -n "$db" ] || continue
  excludes+=(--exclude "$db" --exclude "$db-wal" --exclude "$db-shm")
done < <(jq -r --arg s "$SET" '.sets[$s].sqlite[]?' "$CONFIG")

rsync -a --delete --delay-updates --chown="$OWNER" "${excludes[@]}" \
  --rsync-path="sudo rsync" -e "$RSYNC_RSH" "$SOURCE:$PATH_SRC/" "$PATH_DST/"

stage="$(mktemp -d)"
trap 'rm -rf "$stage"' EXIT
while IFS= read -r db; do
  [ -n "$db" ] || continue
  say "consistent snapshot of $db"
  rsudo "sqlite3 '$PATH_SRC/$db' \".backup '/tmp/offload-$SET-$(basename "$db")'\""
  rsync -a --rsync-path="sudo rsync" -e "$RSYNC_RSH" \
    "$SOURCE:/tmp/offload-$SET-$(basename "$db")" "$stage/$(basename "$db")"
  rsudo "rm -f '/tmp/offload-$SET-$(basename "$db")'"
  install -m 0640 -o "${OWNER%%:*}" -g "${OWNER##*:}" "$stage/$(basename "$db")" "$PATH_DST/$db"
done < <(jq -r --arg s "$SET" '.sets[$s].sqlite[]?' "$CONFIG")

# --- 4. Verify before announcing --------------------------------------------
while IFS= read -r db; do
  [ -n "$db" ] || continue
  check="$(sqlite3 "$PATH_DST/$db" 'PRAGMA integrity_check;' 2>&1 || true)"
  [ "$check" = "ok" ] || die "$db failed integrity_check: $check"
  say "$db integrity_check: ok"
done < <(jq -r --arg s "$SET" '.sets[$s].sqlite[]?' "$CONFIG")

if [ -n "$COUNT_SQL" ]; then
  AFTER="$(local_count)"
  [ "$AFTER" = "$REMOTE_COUNT" ] || die "row count differs: source $REMOTE_COUNT, target $AFTER"
  say "row count matches source: $AFTER"
fi

start_units "$STOP_DST"

if [ -n "$HEALTH_URL" ]; then
  for i in $(seq 1 45); do
    if curl -fsS -m 3 -o /dev/null "$HEALTH_URL"; then
      say "healthy: $HEALTH_URL answered 200 after $((i * 2))s"
      break
    fi
    [ "$i" -eq 45 ] && die "$HEALTH_URL never answered (90s)"
    sleep 2
  done
fi

jq -n --arg set "$SET" --arg source "$SOURCE" --arg manifest "$BEFORE" \
  --arg count "$REMOTE_COUNT" --arg at "$(date -Is)" \
  '{set: $set, source: $source, manifest: $manifest, rows: $count, at: $at}' >"$MANIFEST_FILE"
say "$SET migrated: manifest $BEFORE recorded in $MANIFEST_FILE"
say "the source units [$STOP_SRC] are stopped on $SOURCE; they stay stopped until that host is rebuilt with the service disabled"
